-- Fase 3, enciclopedia-piante-da-arbusti ("Il giardino di arbusti", Edicart 1995,
-- ISBN 8877747056), trascrizioni fornite dall'utente in fonti/ridimensionate/01..18.md
-- (18 file di testo, generi da Abelia a Weigela; 18.md e' solo una tabella riepilogativa
-- per esposizione, non contiene testo narrativo nuovo). Nessuna copertura pregressa di
-- questa fonte in catalogo. Segue il criterio in fonti/criterio-importazione.md: righe
-- PFAF esistenti arricchite in append (mai sovrascritte, regola 1), nuove specie inserite
-- in bozza con on conflict do nothing, fonte tracciata per ogni riga (regola 4). Le cultivar
-- citate solo per nome restano nella descrizione della specie madre (regola 6), mai una
-- riga propria.

update specie set descrizione = descrizione || $t$ Raggiunge 4 m, abbastanza resistente al gelo, ramificazioni pubescenti, foglie caduche oblongo-acuminate, fiori profumati bianchi, fiorisce maggio-giugno.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Abelia triflora$t$) where slug = $t$abelia-triflora$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Abelia triflora$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto vigoroso, foglie verdi pubescenti poi glabre, fiori bianchi in racemi, frutti a drupa nero-bluastri.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amelanchier arborea$t$) where slug = $t$amelanchier-arborea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amelanchier arborea$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. A. oblongifolia: foglie lanceolate bruno-rossastre poi rosso-scarlatte, fiori bianchi di 1 cm in racemi di 2,5-6 cm, frutti a drupa nero-porpora; cresce anche in terra calcarea, spesso confusa con A. lamarckii.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amelanchier canadensis$t$) where slug = $t$amelanchier-canadensis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amelanchier canadensis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alberello a portamento espanso, fioritura abbondante, 4-6 m; foglie bronzee poi arancioni-rossastre, fiori bianchi di 2,5 cm in racemi 4-12 cm, frutti a drupa eduli nero-bluastri; cresce bene in terreno sabbioso.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amelanchier laevis$t$) where slug = $t$amelanchier-laevis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amelanchier laevis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. A. canadensis, A. x grandiflora: albero a portamento espanso alto anche 10 m, foglie ramate sericee da giovani, rosse/arancioni in autunno, fiori rosa-biancastri 1-1,5 cm in racemi, frutti a drupa eduli nero-bluastri; 'Rubescens' ha fiori rosa e non forma polloni; cresce in terriccio di bosco acido o sabbioso.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amelanchier lamarckii$t$) where slug = $t$amelanchier-lamarckii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amelanchier lamarckii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. A. vulgaris, pero corvino: arbusto cespuglioso alto anche 3 m, ramificazioni pubescenti grigie poi porpora-brunastre, foglie ovali pubescenti da giovani, fiori bianchi pubescenti, frutti a drupa eduli blu; vive bene nel sottobosco, in terriccio calcareo.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amelanchier ovalis$t$) where slug = $t$amelanchier-ovalis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amelanchier ovalis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alta 90-120 cm, ramificazioni pubescenti, foglie sessili pennate verde-grigio lunghe 14 cm con 15-45 foglioline, fiori numerosi 5-18 cm brevemente peduncolati in spighe.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amorpha canescens$t$) where slug = $t$amorpha-canescens$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amorpha canescens$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Falso indaco: arbusto sinuoso alto 4-5 m, ramificazioni pubescenti, foglie pennate fino a 6 cm, fiori porpora-violacei 9-18 cm con stami gialli in spighe; cresce bene in terricci umidi e arenosi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Amorpha fruticosa$t$) where slug = $t$amorpha-fruticosa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Amorpha fruticosa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto esile alto 2-3 m, ramificazioni lanuginose, fiori bianchi o rosa di 1 cm in corimbi di 9-20 fiori, frutti rossi 5-7 mm; 'Brilliant' ha numerosi frutti rossi; adatta a terreni asciutti.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Aronia arbutifolia$t$) where slug = $t$aronia-arbutifolia$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Aronia arbutifolia$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Cresce bene in terra umida, 50-100 cm, foglie verdi poi rosso-brunastre, fiori bianchi, frutti neri globosi lucenti 6-8 mm; 'Aron' ha frutti più grossi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Aronia melanocarpa$t$) where slug = $t$aronia-melanocarpa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Aronia melanocarpa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Della Cina occidentale, resistente al gelo, pieno sole, alto fino a 1,5 m, foglie caduche strette che in autunno si tingono d'arancione, fiori gialli in racemi, frutti giallo-arancioni o color salmone.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis aggregata$t$) where slug = $t$berberis-aggregata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis aggregata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Del Cile e Argentina, alto anche 2 m, fiorisce aprile-maggio, foglie persistenti ovali lunghe 1,7 cm con spine, fiori solitari giallo-oro, frutti nero-bluastri; 'Nana' varietà più compatta.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis buxifolia$t$) where slug = $t$berberis-buxifolia$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis buxifolia$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Del Cile, alto 1-3 m, fiorisce abbondantemente in aprile-maggio, foglie persistenti, densi racemi penduli di 10-30 fiori giallo-arancio (1,4 cm); predilige terreni umidi, acidi, pieno sole.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis darwinii$t$) where slug = $t$berberis-darwinii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis darwinii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Della Corea, alto fino a 1,5 m, ramificazioni rigide, foglie caduche verde opaco poi rosso scuro, frutti rosso brillante persistenti a lungo; non sensibile alla ruggine.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis koreana$t$) where slug = $t$berberis-koreana$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis koreana$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Del Giappone, vigoroso, alto 1-1,5 m, foglie caduche lunghe 3,5 cm, fiori giallo chiaro solitari, frutti rossi; adatto a siepi anche in terriccio povero; 'Atropurpurea Nana' nana con colori autunnali, 'Aurea' foglie gialle, 'Rose Glow' foglie striate di rosa.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis thunbergii$t$) where slug = $t$berberis-thunbergii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis thunbergii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Crespino, cresce spontaneo nelle regioni settentrionali d'Europa e in Italia; un tempo sradicato perché ospite della ruggine del grano.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis vulgaris$t$) where slug = $t$berberis-vulgaris$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis vulgaris$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Incrocio naturale di B. linearifolia e B. darwinii, foglie persistenti, abbastanza resistente al gelo, alto anche 3 m, fiori color albicocca, frutti neri.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis x lologensis$t$) where slug = $t$berberis-x-lologensis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis x lologensis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Incrocio di B. empetrifolia e B. darwinii, non soffre il gelo, 2 m x 3 m, ramificazioni arcuate eleganti, fiori giallo-oro in racemi di 4-14 fiori; 'Crawley Gem' alto 60 cm con fioritura abbondante giallo-rossiccia.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Berberis x stenophylla$t$) where slug = $t$berberis-x-stenophylla$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Berberis x stenophylla$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Var. repens, più resistente al gelo, 30-100 cm x 2 m, foglie persistenti verde scuro-lucenti 5 cm, fiori blu chiaro a inizio estate e spesso in autunno; tollera la siccità.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ceanothus thyrsiflorus$t$) where slug = $t$ceanothus-thyrsiflorus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ceanothus thyrsiflorus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Cotogno del Giappone: chioma ampia, alto anche 1 m, fiorisce aprile-maggio, foglie glabre ovato-oblunghe verde chiaro, fiori da color salmone a rosso-arancio 2-4 cm, frutti gialli profumati 3-4 cm.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles japonica$t$) where slug = $t$chaenomeles-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. C. lagenaria: chioma ampia, supera 2 m, fiorisce marzo/maggio, foglie glabre dentate 4-10 cm, fiori rosso-rosati/rosa/bianchi 3,5 cm, frutti profumati gialli 8 cm; cultivar 'Moerloosii', 'Simonii', 'Umbilicata'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles speciosa$t$) where slug = $t$chaenomeles-speciosa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles speciosa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Incrocio di C. japonica e C. speciosa, varietà nana vigorosa a fioritura abbondante; 'Boule de Feu', 'Crimson and Gold', 'Fire Dance', 'Pink Lady', 'Rowallane'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles x superba$t$) where slug = $t$chaenomeles-x-superba$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Chaenomeles x superba$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Calicanto: forma compatta nelle regioni temperate, foglie caduche ruvide oblungo-lanceolate 5-15 cm, fiori fortemente profumati campanulati giallo-verdognoli e porpora al centro (2-2,5 cm); 'Grandiflorus' fiori meno profumati giallo intenso macchiati di rosso, 'Luteus' fiori tutti gialli; cresce meglio contro un muro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Chimonanthus praecox$t$) where slug = $t$chimonanthus-praecox$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Chimonanthus praecox$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Originaria degli USA orientali, 2-10 m, fusti pubescenti, foglie 10-20 cm, fiori bianco-verdognoli 2-5 cm in infiorescenze fino a 15 cm; specie dioica, frutti a drupa blu scuro solo con esemplare maschile vicino.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Chionanthus virginica$t$) where slug = $t$chionanthus-virginicus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Chionanthus virginica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. C. tatarica: resistente al gelo, 3-4 m, fiorisce aprile-maggio/giugno, grandi foglie ellittiche, fiori bianco crema 3,5 cm, frutti globosi bianco perlacei o blu metallico; 'Elegantissima' (sin. Argenteomarginata) ramificazioni rosso intenso; 'Sibirica' più bassa (1,5 m), rosso acceso.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus alba$t$) where slug = $t$cornus-alba$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus alba$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto vigoroso, fiorisce maggio-giugno, ramificazioni rosso-brunastre, piccoli fiori bianchi in corimbi, frutti blu scuro; 'Argentea' foglie variegate di bianco.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus alternifolia$t$) where slug = $t$cornus-alternifolia$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus alternifolia$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Adatta a formare tappeti, 10-20 cm, fiorisce giugno-luglio, ramificazioni striscianti, fiori verdi con brattee bianche in capolini, frutti eduli rosso-arancioni; tollera l'ombra e terriccio un po' acido.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus canadensis$t$) where slug = $t$cornus-canadensis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus canadensis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Resistente al gelo, fusto 3-10 m, ramificazioni pendenti bruno-grigiastre, corimbi color crema (giugno-luglio), frutti blu scuro; 'Variegata' foglie verdi marginate di bianco.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus controversa$t$) where slug = $t$cornus-controversa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus controversa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 4-5(-10) m x 2-4 m, fiorisce maggio prima delle foglie, che in autunno si tingono di arancione/rosso porpora; fiori gialli circondati da 4 brattee bianche di 10 cm, frutti rossi in densi grappoli; 'Rubra' brattee rosa; adatta a terreni acidi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus florida$t$) where slug = $t$cornus-florida$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus florida$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 4-6 m x 3 m, chioma ampia, fiorisce maggio-giugno, foglie ovali lucide rosse in autunno, grandi brattee bianco crema con punta rossa, frutti rossi; non tollera argilla, splendida isolata.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus kousa$t$) where slug = $t$cornus-kousa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus kousa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Corniolo, 2-7 m x 2-4 m, fiorisce prima delle foglie (febbraio-aprile), fiori gialli peduncolati in capolini ombrelliformi, frutti eduli rosso sanguigno; spontaneo in Italia, predilige terriccio asciutto.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus mas$t$) where slug = $t$cornus-mas$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus mas$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Può raggiungere 25 m, foglie che in autunno diventano rosso sanguigno, brattee 4-7 bianche o rosa, frutti rosso pallido; adatta a terreni leggermente acidi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus nuttallii$t$) where slug = $t$cornus-nuttallii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus nuttallii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sanguinella, spontanea in Italia in terreni asciutti e calcarei, 2,5-4 m, ramificazioni rosse poi rosso-brunastre, fiori bianchi (maggio-giugno) in cime terminali, frutti blu scuro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus sanguinea$t$) where slug = $t$cornus-sanguinea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus sanguinea$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. C. sericea: fusto cespuglioso 2-2,5 m, ramificazioni verdi poi rosso acceso/rosso-bruno, fiori biancastri 3,5 cm, frutti bianchi, fiorisce giugno-luglio; 'Flaviramea' corteccia e rami verde-giallognoli.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cornus stolonifera$t$) where slug = $t$cornus-sericea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cornus stolonifera$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Nocciolo di Costantinopoli, alto anche 20 m, resistente all'inquinamento, chioma larga ovale o piramidale, corteccia grigio-chiara sugherosa; amenti giallo-bruni all'inizio della primavera.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Corylus colurna$t$) where slug = $t$corylus-colurna$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Corylus colurna$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Filbert' ha foglie e frutti più grandi; 'Atropurpurea' (nocciolo a foglie rosse) alta fino a 6 m con foglie rosso-vinoso-scuro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Corylus maxima$t$) where slug = $t$corylus-maxima$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Corylus maxima$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alto 1-2 m, compatto, meno resistente al gelo, foglie persistenti piccole (1 cm), fiori piccoli bianchi numerosi, frutti rosso-arancio; richiede posizione soleggiata calda riparata.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster conspicuus$t$) where slug = $t$cotoneaster-conspicuus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster conspicuus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alto 2 m, fusti sottili arcuati, foglie caduche quasi rotonde rosso-vermiglie in autunno, fiori rosa, frutti rossi; adatto a siepi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster divaricatus$t$) where slug = $t$cotoneaster-divaricatus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster divaricatus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Chioma ampia, alto 2 m, fusti arcuati eleganti, foglie quasi persistenti verde chiaro-lucenti 2-3 cm, fiori rosa, frutti rosso-arancioni; coltivabile isolata o in gruppi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster franchetii$t$) where slug = $t$cotoneaster-franchetii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster franchetii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Var. soongoricus, alto 3 m, fusti grigi pubescenti, foglie caduche ovali verde opaco, fiori bianchi pubescenti in corimbi, frutti numerosi rossi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster racemiflorus$t$) where slug = $t$cotoneaster-racemiflorus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster racemiflorus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Portamento eretto per siepi, 3-4 m, ramificazioni rigide tomentose, foglie quasi persistenti verde lucido, fiori bianco-rosati, frutti numerosi rosso scuro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster simonsii$t$) where slug = $t$cotoneaster-simonsii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster simonsii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Portamento eretto, 4-5 m, foglie quasi persistenti verde opaco; 'Cornuba' frutti rosso acceso numerosi, 'John Waterer' grandi corimbi bianchi dall'odore sgradevole e frutti grossi rosso-vermiglio-lucenti, 'Pendula' ramificazioni prostrate a foglie caduche.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster x watereri$t$) where slug = $t$cotoneaster-x-watereri$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cotoneaster x watereri$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Albero ad ampia chioma, 4-6 m, foglie ovali leggermente divise non pelose, corimbi di 15-20 fiori bianchi, frutti rossi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Crataegus crus-galli$t$) where slug = $t$crataegus-crus-galli$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Crataegus crus-galli$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. C. oxyacantha, biancospino: fino a 4 m, due o più tronchi spinosi (spine fino a 2,5 cm), grandi foglie ovali 3-5 lobi dentati, fiori bianchi in corimbi, frutti rossi; 'Alboplena', 'Gireoudii', 'Paul's Scarlet' (7 m, fiori doppi rosso-vermigli).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Crataegus laevigata$t$) where slug = $t$crataegus-laevigata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Crataegus laevigata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Portamento leggermente prostrato, non soffre il gelo, richiede terriccio calcareo, fiorisce abbondantemente maggio-giugno, fusti leggermente pubescenti, fiori giallo-oro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cytisus decumbens$t$) where slug = $t$cytisus-decumbens$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cytisus decumbens$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ginestra dei carbonai, soffre il gelo, alta 2-2,5 m, ramificazioni numerose aggrovigliate, cresce spontanea in Italia, fiorisce maggio-giugno e agosto-settembre, fiori giallo-oro; 'Andreanus', 'Burkwoodii', 'Palette'; tutte le ginestre difficili da trapiantare.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Cytisus scoparius$t$) where slug = $t$cytisus-scoparius$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Cytisus scoparius$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alta 40-100 cm, foglie persistenti, fiori verdognoli profumati di sera nascosti tra il fogliame, frutti neri; posizioni umide e ombreggiate.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Daphne laureola$t$) where slug = $t$daphne-laureola$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Daphne laureola$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Mezereo, ramificato, alto 1 m, fiorisce febbraio-marzo, foglie caduche lanceolate verdi-grigiastre, spighette bianche/rosso-rosate/porpora profumate, frutti rossi; 'Alba' fiori bianchi frutti gialli, 'Grandiflora' fiori rosa, 'Ruby Glow' rosa porpora-scuro.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Daphne mezereum$t$) where slug = $t$daphne-mezereum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Daphne mezereum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alta 1 m, fiorisce febbraio-marzo, soffre il gelo, posizione riparata e ombra, foglie persistenti, fiori profumati rosa-biancastri; 'Aureomarginata' più resistente, foglie margini gialli.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Daphne odora$t$) where slug = $t$daphne-odora$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Daphne odora$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. D. crenata: portamento eretto, 2-3 m, fiorisce giugno-luglio, foglie ovato-oblunghe dentate 3-8 cm, fiori bianchi sfumati di rosa in racemi stretti; 'Plena' fiori doppi bianchi con striature rosa esterne.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Deutzia scabra$t$) where slug = $t$deutzia-scabra$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Deutzia scabra$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Portamento cespuglioso, alta 40 cm, ampi fiori gialli aprile-giugno e anche in settembre.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Genista pilosa$t$) where slug = $t$genista-pilosa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Genista pilosa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ginestrella o baccellina, portamento eretto, 50-100 cm, fiorisce giugno-agosto, ramificazioni tenaci pubescenti, fiori giallo-oro in lunghi racemi; 'Royal Gold' forma arrotondata compatta.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Genista tinctoria$t$) where slug = $t$genista-tinctoria$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Genista tinctoria$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto cespuglioso a crescita lenta, tanto largo quanto alto, in natura fino a 10 m; foglie ovato-acuminate 5-10 cm, fiori bianchi tubulosi 1-2 cm in gruppi di 2-7, frutti alati 3,5 cm; var. monticola più simile ad albero, fino a 24 m.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Halesia carolina$t$) where slug = $t$halesia-carolina$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Halesia carolina$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Unica specie del genere, dei deserti salati dell'Asia occidentale/settentrionale, adatta a giardini costieri; alta 2 m, ramificazioni spinose verdi-grigiastre, foglie pennate grigiastre, racemi penduli di 2-4 fiori profumati lilla o porpora (1 cm); predilige terriccio alcalino/sabbioso.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Halimodendron halodendron$t$) where slug = $t$halimodendron-halodendron$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Halimodendron halodendron$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Raggiunge 4 m, chioma ampia, fiorisce settembre-ottobre, foglie dentate giallo-oro in autunno, piccoli fiori giallo chiaro all'apparire dei frutti (maturano l'autunno successivo); corteccia/rami/succo/radici usati in medicina; predilige ombra e terreno umido acido.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hamamelis virginiana$t$) where slug = $t$hamamelis-virginiana$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hamamelis virginiana$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ibisco della Siria, arbusto eretto, 2-3 m, foglie caduche trilobate verdi 4-10 cm, fiori semplici rosso-purpurei con venature scure 5-10 cm; molte varietà ('Blue Bird', 'Boule de Feu', 'Hamabo', 'Mauve Queen', 'Red Heart', 'Woodbridge'); sensibile alle farfalline bianche aleurodidi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hibiscus syriacus$t$) where slug = $t$hibiscus-syriacus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hibiscus syriacus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Olivello spinoso, sin. H. rhamnoides maritima, spontaneo in Italia, forma sferica, 2-5 m (più basso in zone costiere), ramificazioni spinose argentate scagliose, frutti arancioni in grappoli sulle piante femminili; si diffonde per polloni radicali, resiste al vento salato e all'inquinamento; per fruttificare servono esemplari maschili e femminili vicini.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hippophae rhamnoides$t$) where slug = $t$hippophae-rhamnoides$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hippophae rhamnoides$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. Spiraea discolor, la più coltivata del genere: chioma ampia, 2,5-3 m, ramificazioni sottili spesso bruno-rossicce, fiori bianco crema con stami numerosi in spighe terminali pendule; indicata anche per fogliame di sottofondo.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Holodiscus discolor$t$) where slug = $t$holodiscus-discolor$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Holodiscus discolor$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fusto cespuglioso 1-2 m, fiorisce luglio-agosto, corimbi piatti 5-20 cm; 'Annabelle' e 'Grandiflora' grandi corimbi arrotondati bianchi; cresce bene in posizione un po' ombreggiata, terra fertile calcarea, potatura radicale in primavera.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hydrangea arborescens$t$) where slug = $t$hydrangea-arborescens$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hydrangea arborescens$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 2 m, fiorisce luglio-agosto, soffre i forti geli, posizione riparata ombreggiata; sottospecie sargentiana (sin. H. sargentiana) non soffre il gelo, corimbi 12-20 cm; var. strigosa macrophylla 1,75 m, terreni argillosi leggermente in ombra.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hydrangea aspera$t$) where slug = $t$hydrangea-aspera$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hydrangea aspera$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Varietà alte 70-150 cm, fioritura luglio-settembre: 'Ayesha' fiori profumati bianco-lilla, 'Blue Wave' blu (terriccio acido) o rosa/lilla, 'Mariesii Perfecta' rosa-lilla, 'Veitchii' bianchi; crescono bene anche presso il mare.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hydrangea macrophylla$t$) where slug = $t$hydrangea-macrophylla$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hydrangea macrophylla$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alta 4 m, fiorisce agosto-settembre, foglie marrone-gialle in autunno, fiori bianchi o rosa in grandi infiorescenze dense; 'Grandiflora' fiori sterili bianchi poi rosa poi rossi; richiede terriccio umido, potatura annuale.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hydrangea paniculata$t$) where slug = $t$hydrangea-paniculata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hydrangea paniculata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. H. macrophylla serrata: portamento eretto, fusto 1-1,5 m, fiorisce luglio-agosto, corimbi appiattiti 14 cm blu in terra acida; 'Acuminata', 'Blue Bird', 'Rosalba'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hydrangea serrata$t$) where slug = $t$hydrangea-serrata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hydrangea serrata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ciciliana o tutta-sana, piccolo arbusto eretto ramificato alto 1 m, spontaneo in Italia nelle zone umide dei boschi, foglie profumate rosse poi verde acceso, fiori giallo-oro 2-3 cm, frutti rossi poi neri.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hypericum androsaemum$t$) where slug = $t$hypericum-androsaemum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hypericum androsaemum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Alto 30 cm, foglie in genere persistenti, forma cespugli larghi e bassi, fiori solitari giallo-oro 6-10 cm con grossi stami dalle antere rossicce; resiste alla siccità, vegeta bene all'ombra, si adatta a qualunque terreno.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Hypericum calycinum$t$) where slug = $t$hypericum-calycinum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Hypericum calycinum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. I. gerardiana, alta 1-1,5 m, numerose ramificazioni ricurvate, foglie imparipennate pubescenti con 13-21 foglioline, spighe erette 7-15 cm di fiori rosa-violetti; protezione alla base in caso di forti geli.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Indigofera heterantha$t$) where slug = $t$indigofera-heterantha$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Indigofera heterantha$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto compatto ampio, 50-100 cm, ramificazioni ricurve, foglie imparipennate con 7-11 foglioline, fiori rosa o porpora-rossicci 2 cm in spighe compatte peduncolate lunghe 12 cm.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Indigofera kirilowii$t$) where slug = $t$indigofera-kirilowii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Indigofera kirilowii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Unica specie del genere, dell'Estremo Oriente: chioma ampia compatta, ramificazioni sottili verdi arcuate, foglie ovali acuminate inciso-dentate 4-7 cm, fiori gialli numerosi 2,5-5 cm con 5 petali; 'Pleniflora' più alta con fiori doppi più scuri; si propaga per polloni radicali.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Kerria japonica$t$) where slug = $t$kerria-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Kerria japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. Cytisus alpinus, maggiociondolo alpino: albero elegante fino a 8 m x 3-4 m, fiorisce giugno, fusti verde-grigio-giallognoli, fiori gialli profumati in racemi 20-30 cm, legumi 6 cm.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Laburnum alpinum$t$) where slug = $t$laburnum-alpinum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Laburnum alpinum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. L. vulgare, maggiociondolo: fino a 8 m x 3-4 m, fiorisce maggio-giugno, ramificazioni pubescenti, fiori giallo-oro inodori in lunghi racemi a grappolo; 'Pendulum' rami prostrati ricurvi per piccoli giardini. Foglie e frutti velenosi per uomini e animali domestici.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Laburnum anagyroides$t$) where slug = $t$laburnum-anagyroides$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Laburnum anagyroides$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ La più coltivata del genere (più resistente al gelo): arbusto nano, fusti robusti cavi verde-acqua, foglie caduche opposte pubescenti, fiori imbutiformi rossi/viola/bianchi 2 cm in grappoli penduli con brattee rosse o porpora persistenti, frutti rosso porpora poi violaceo-nerastri apprezzati dai fagiani; richiede copertura invernale alla base.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Leycesteria formosa$t$) where slug = $t$leycesteria-formosa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Leycesteria formosa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ligustro lucido, tollera bene l'ombra, alto anche 3 m, fiorisce agosto-settembre, soffre il gelo, foglie persistenti coriacee ovali-acute verde scuro 8-12 cm, fiori numerosi bianchi in pannocchie 15-20 cm, bacche nero-bluastre.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ligustrum lucidum$t$) where slug = $t$ligustrum-lucidum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ligustrum lucidum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ligustro, compatto eretto, foglie quasi persistenti ovali lucide fino a 6 cm, fiori bianchi in pannocchie dense 6-10 cm, frutti spesso restano verdi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ligustrum ovalifolium$t$) where slug = $t$ligustrum-ovalifolium$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ligustrum ovalifolium$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Var. stauntonii, arbusto nano a chioma ampia, fiorisce luglio-agosto, soffre il gelo, ramificazioni violacee pubescenti, foglie caduche ovali 3-4 cm, pannocchie pendule 6-10 cm.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ligustrum sinense$t$) where slug = $t$ligustrum-sinense$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ligustrum sinense$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ligustro comune, vigoroso fino a 5 m, esteso apparato radicale, fiori numerosi bianchi molto profumati in dense pannocchie 4-6 cm (attirano api e farfalle), bacche nere persistenti apprezzate dai fagiani; foglie e bacche velenose per l'uomo; 'Aureum' foglie gialle; cresce anche su suoli poveri sabbiosi calcarei, protegge dall'erosione.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ligustrum vulgare$t$) where slug = $t$ligustrum-vulgare$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ligustrum vulgare$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Rampicante che non soffre il gelo, adatto anche a formare tappeti, foglie quasi persistenti verde scuro, fiori rosso-arancio, frutti numerosi neri fino a dicembre.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Lonicera henryi$t$) where slug = $t$lonicera-henryi$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Lonicera henryi$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Caprifoglio della Cina/Giappone, fusto rampicante 4-8 m, non soffre il gelo, fiori imbutiformi bianchi poi giallastri profumati (giugno-settembre), frutti neri; 'Aureoreticulata' foglie reticolate di giallo.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Lonicera japonica$t$) where slug = $t$lonicera-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Lonicera japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Caprifoglio comune nelle siepi dell'Italia centrosettentrionale, fusto rampicante fino a 6 m, fiorisce giugno-agosto, non soffre il gelo, tollera l'ombra, fiori bianco-giallognoli profumati soprattutto di notte; 'Belgica', 'Serotina'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Lonicera periclymenum$t$) where slug = $t$lonicera-periclymenum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Lonicera periclymenum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. M. tomentosa: fusto arbustivo o arborescente fino a 10 m, chioma larga, fiorisce abbondantemente dopo 10-15 anni (aprile-maggio), corteccia profumata se sfiorata, fiori a tulipano bianchi leggermente rosa alla base fino a 10 cm, frutti rossi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Magnolia kobus$t$) where slug = $t$magnolia-kobus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Magnolia kobus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Magnolia stellata, crescita lenta, alta 2 m, chioma larga, ramificazioni sericee, fiori numerosi bianchi 7-8 cm con 12-20 petali stretti; 'Royal Star' crescita più vigorosa.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Magnolia stellata$t$) where slug = $t$magnolia-stellata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Magnolia stellata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. Berberis aquifolium: pianta cespitosa eretta a chioma larga, crescita lenta, 50-100(-200) cm, fiorisce aprile-maggio, foglie ovali dentate verde-lucente rossastre in inverno, fiori profumati gialli in brevi grappoli, bacche numerose blu; 'Apollo' alto 50 cm fiorisce profusamente, tappezzante.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Mahonia aquifolium$t$) where slug = $t$mahonia-aquifolium$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Mahonia aquifolium$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. Berberis japonica, maonia del Giappone, predilige l'ombra, fusto 1 m, foglie da verde scuro a blu metallico, racemi penduli di fiori profumati giallo-cromo (febbraio-marzo); 'Hivernant' (sin. 'Hiemalis') fusto più alto, foglie rossastre in inverno.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Mahonia japonica$t$) where slug = $t$mahonia-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Mahonia japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Vedi M. x wagneri 'Pinnata' (sinonimo): arbusto vigoroso 1-2 m, fiorisce marzo-aprile, foglie da grigio a verde metallico, fiori giallo acceso in racemi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Mahonia pinnata$t$) where slug = $t$mahonia-pinnata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Mahonia pinnata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Charity', fusto cespuglioso eretto, alto 2 m, fiorisce in inverno se riparato dal gelo, foglie verde-grigiastre, fiori gialli in grandi racemi, tollera bene l'ombra.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Mahonia x media$t$) where slug = $t$mahonia-x-media$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Mahonia x media$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto ramificato, 4-5(-10) m, foglie ovato-lanceolate verde scuro 5-15 cm, fiori profumati bianchi (aprile-maggio), innumerevoli frutti ovali color porpora.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Osmanthus decorus$t$) where slug = $t$osmanthus-decorus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Osmanthus decorus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arbusto arrotondato compatto, 2-3(-8) m, fiorisce settembre-novembre, foglie coriacee simili all'agrifoglio 5 cm con margine spesso spinoso, fiori profumati bianco crema, frutti rari color porpora; numerose cultivar a foglie variegate.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Osmanthus heterophyllus$t$) where slug = $t$osmanthus-heterophyllus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Osmanthus heterophyllus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. x Osmarea burkwoodii, sviluppo lento, 1-2 m, fiorisce aprile-maggio, foglie coriacee ovali 5 cm margine seghettato, fiori profumati bianchi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Osmanthus x burkwoodii$t$) where slug = $t$osmanthus-x-burkwoodii$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Osmanthus x burkwoodii$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. P. aculeatus, marruca, giuggiolo selvatico: fusto arborescente o cespuglioso 3(-6) m, foglie ovali finemente dentate 2-4 cm con stipole aculeato-spinose, fiori gialli in ombrelle, frutti gialli a disco 2-3 cm; secondo tradizione la corona di spine di Cristo sarebbe stata fatta con i suoi fusti; resistente alla siccità.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Paliurus spina-christi$t$) where slug = $t$paliurus-spina-christi$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Paliurus spina-christi$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fiore degli angeli o canestro, cespuglioso compatto, alto 2 m, corteccia squamosa bruno scuro, foglie ovali 4-9 cm, racemi di 5-9 fiori profumati bianchi con cuore giallo (maggio-giugno); si adatta a suoli poveri e asciutti, resiste a potature radicali.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Philadelphus coronarius$t$) where slug = $t$philadelphus-coronarius$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Philadelphus coronarius$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sviluppo lento, compatta, 2-4 m, ramificazioni allungate ricurve, foglie coriacee strette da verde-lucente a color bronzo, fiori bianchi in grappoli; da questa specie molte cultivar con fiori bianchi/rosa/rossi e foglie colorate.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Pieris japonica$t$) where slug = $t$pieris-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Pieris japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. Citrus trifoliata, arancio trifogliato, unica specie del genere: ramificazioni spinose angolose rigide, foglie composte di 3 foglioline verdi poi gialle, fiori bianchi profumati (4-5 petali), frutti autunnali non commestibili simili all'arancio (4-5 cm); fiorisce prima delle foglie; rami invernali decorativi per fiori recisi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Poncirus trifoliata$t$) where slug = $t$poncirus-trifoliata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Poncirus trifoliata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Rhexii', marasca/visciolo, fusto arborescente fino a 8 m con polloni alla base, fiori doppi bianchi 3 cm con stami gialli (maggio).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus cerasus$t$) where slug = $t$prunus-cerasus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus cerasus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Portamento arbustivo o arborescente, fioritura abbondante, coltivata come bonsai in Giappone; l'arbusto cespuglioso raggiunge 2-3 m, fiorisce fine marzo-inizio aprile, fiori numerosi bianchi con calice e ricettacolo rosa scuro; numerose cultivar nane.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus incisa$t$) where slug = $t$prunus-incisa$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus incisa$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Meno resistente al gelo, 3-4 m, fiorisce abbondantemente in giugno (età adulta), foglie persistenti ovali lucenti 7-10 cm su rami rosso scuro, grandi fiori bianchi, frutti neri; adatta a coprire muri o formare siepi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus lusitanica$t$) where slug = $t$prunus-lusitanica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus lusitanica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Klara Mayer', pesco ornamentale, arbusto o albero eretto ampio fino a 5 m, fiori doppi rosa acceso 3,5 cm (aprile).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus persica$t$) where slug = $t$prunus-persica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus persica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Fukubana', ramificato eretto, 2-3 m, fiorisce abbondantemente aprile-maggio, foglie verde-bronzo, boccioli rosso porpora, fiori semidoppi rosa scuro; 'Pendula' ricadente, 'Autumnalis' fiorisce novembre-dicembre.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus subhirtella$t$) where slug = $t$prunus-subhirtella$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus subhirtella$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. P. nana, piccolo arbusto grazioso, 1-1,5 m, forma numerosi polloni, indicato per giardini rocciosi; ramificazioni grigio-argentate poi grigio-bruno chiaro, mazzetti di 1-3 fiori rosso-rosati in aprile.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus tenella$t$) where slug = $t$prunus-tenella$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus tenella$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Arrotondato, largo 2 m, foglie trilobate, fiori doppi rosa simili alla rosa che ricoprono i rami marzo-aprile; potare radicalmente subito dopo la fioritura.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Prunus triloba$t$) where slug = $t$prunus-triloba$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Prunus triloba$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ibridi di R. ponticum e R. rustica: arbusti a foglie caduche 1,5-2,5 m; 'Coccinea Speciosa', 'Freya', 'Nancy Waterer', 'Norma'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Rhododendron ponticum$t$) where slug = $t$rhododendron-ponticum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Rhododendron ponticum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fusto arbustivo eretto, 2-2,5 m, foglie verde scuro, fiori rosa/rosso porpora/bianchi in grappoli dall'odore poco gradevole, frutti blu; 'King Edward VII' rosso acceso, 'Tydeman's White' quasi bianco.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Ribes sanguineum$t$) where slug = $t$ribes-sanguineum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Ribes sanguineum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Robinia pelosa, chioma larga, 1-1,5 m, fiorisce giugno e spesso a fine estate, rami senza spine dapprima rossicci ispidi poi verdi con punte rosse, foglie con 9-13 foglioline, fiori rosa o bianco-rosati in grappoli.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Robinia hispida$t$) where slug = $t$robinia-hispida$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Robinia hispida$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Salice bianco, tra le specie più diffuse in Italia e nel nord Europa insieme al salicone (S. caprea) e S. repens.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Salix alba$t$) where slug = $t$salix-alba$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Salix alba$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Salicone, chioma ampia fusto eretto, 3(-9) m, produce in marzo amenti pubescenti bianco-argentati che diventano gialli; 'Kilmarnock' (sin. 'Pendula') varietà bassa con rami pendule.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Salix caprea$t$) where slug = $t$salix-caprea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Salix caprea$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ 'Wehrhahnii', elegante ramificato, 1-2 m, rami bruno-porpora in inverno, amenti bianco-argentati 5 cm (marzo-aprile), foglie ovali 3-6 cm; posizione soleggiata, suolo umido, adatta a giardini rocciosi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Salix hastata$t$) where slug = $t$salix-hastata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Salix hastata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Lento sviluppo, alto 60 cm, chioma ampia, ramificazioni rigide bianche pubescenti, foglie sericee 3-7 cm, amenti maschili gialli (5 cm) e femminili verdi (8 cm) in maggio; cresce bene in giardini rocciosi, posizione fresca ombreggiata.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Salix lanata$t$) where slug = $t$salix-lanata$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Salix lanata$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. S. incana, crespolina o santolina, compatta ramificata, 30-50 cm, ramificazioni argentate cotonose, foglie aromatiche, numerosi capolini giallo acceso; 'Edward Bowles' portamento più aperto, foglie grigiastre.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Santolina chamaecyparissus$t$) where slug = $t$santolina-chamaecyparissus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Santolina chamaecyparissus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. S. virens, portamento ampio, 40-50 cm, foglie glabre rigide verdi, capolini giallo acceso dai peduncoli sottili.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Santolina rosmarinifolia$t$) where slug = $t$santolina-rosmarinifolia$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Santolina rosmarinifolia$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Spirea del Giappone, fusto arbustivo eretto, chioma ampia, fiori rosso-rosato in corimbi (giugno-agosto); numerose cultivar tra cui 'Albiflora' (50 cm, fiori bianchi) e 'Little Princess' (40-60 cm, fiori rosa).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Spiraea japonica$t$) where slug = $t$spiraea-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Spiraea japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Chioma ampia, raggiunge 5 m (gli alberi 10 m), fioritura abbondante, foglie caduche ellittiche 3-8 cm, fiori numerosi bianchi leggermente odorosi in grappoli sui rami orizzontali, drupe verdi lungamente pedunculate.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Styrax japonica$t$) where slug = $t$styrax-japonica$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Styrax japonica$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Nota da millenni per la resina 'storace', dal profumo gradevolissimo; una delle poche specie del genere presenti nelle regioni mediterranee (il genere è per lo più asiatico).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Styrax officinalis$t$) where slug = $t$styrax-officinalis$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Styrax officinalis$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fusto rigido eretto, 2-4 m, ramificazioni verde-oliva, gemme rosso-bruno, fiori viola scuro profumati in grandi pannocchie allungate (maggio/giugno-luglio); indicata per siepi.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Syringa josikaea$t$) where slug = $t$syringa-josikaea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Syringa josikaea$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Lillà, serenella, fusto eretto 4-7 m, fiori numerosi profumati color lilla/blu/bianco/rosso, semplici o doppi, in pannocchie piramidali 20-30 cm (maggio-giugno); importante per l'industria dei fiori recisi; molte varietà tra cui 'Andenken an Ludwig Spath', 'Charles Joly', 'Katherine Havemeyer', 'Madame Lemoine', 'Michael Buchner'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Syringa vulgaris$t$) where slug = $t$syringa-vulgaris$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Syringa vulgaris$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Vigorosa (da potare dopo la fioritura), 3-5 m, numerosissimi racemi spiciformi di fiori persistenti rosa scuro (aprile-maggio), ramificazioni ricurve rosso porpora.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Tamarix parviflora$t$) where slug = $t$tamarix-parviflora$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Tamarix parviflora$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. T. odessana, T. pentandra: fusto arborescente (da potare in primavera), 3-5 m, ramificazioni verdi poi rosso-porpora, foglie verde metallico, fiori rosa chiaro in grandi pennacchi terminali (luglio-settembre).$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Tamarix ramosissima$t$) where slug = $t$tamarix-ramosissima$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Tamarix ramosissima$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. T. africana, soffre i forti geli, fusto 3 m, numerosi grappoli di fiori rosa acceso a petali ricadenti (aprile-maggio) sui rami dell'anno precedente; indicata per rivestire muri.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Tamarix tetranda$t$) where slug = $t$tamarix-africana$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Tamarix tetranda$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fusto cespuglioso eretto, alto anche 150 cm, foglie caduche acute 9 cm color porpora in autunno, fiori bianchi o rosa chiaro, deliziose bacche blu prodotte in abbondanza che a maturazione diventano bianche.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Vaccinium corymbosum$t$) where slug = $t$vaccinium-corymbosum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Vaccinium corymbosum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Mirtillo nero, una delle 3 specie spontanee in Italia insieme a V. vitis-idaea e V. uliginosum.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Vaccinium myrtillus$t$) where slug = $t$vaccinium-myrtillus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Vaccinium myrtillus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Mirtillo di palude, una delle 3 specie spontanee in Italia insieme a V. vitis-idaea e V. myrtillus.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Vaccinium uliginosum$t$) where slug = $t$vaccinium-uliginosum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Vaccinium uliginosum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Mirtillo rosso, compatto prostrato, 10-30 cm, foglie persistenti coriacee ovali verde-lucente 1-2,5 cm, fiori piccoli bianchi, bacche numerose grandi rosse in grappoli penduli; si presta a formare tappeti.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Vaccinium vitis-idaea$t$) where slug = $t$vaccinium-vitis-idaea$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Vaccinium vitis-idaea$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Sin. V. fragrans, fusto eretto, 2-3 m, foglie caduche ovali dentate 5-8 cm, fiori profumati bianchi sfumati di rosa (novembre-dicembre-febbraio); posizione riparata.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Viburnum farreri$t$) where slug = $t$viburnum-farreri$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Viburnum farreri$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Pallone di neve, comune nei luoghi montuosi italiani, fusto alto 4 m, foglie caduche trilobate, cime ombrelliformi (maggio) con fiori fertili piccoli giallastri e sterili grandi bianchi, bacche rosse in grappoli penduli; 'Compactum', 'Notcutt's Variety', 'Roseum'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Viburnum opulus$t$) where slug = $t$viburnum-opulus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Viburnum opulus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Chioma ampia, alto 3 m, fiorisce maggio-giugno, foglie ovali 7-12 cm rosso porpora in autunno, fiori sterili bianchi in cime globose; 'Mariesii' 1,5 m x 3-4 m, 'Nanum Semperflorens' (sin. 'Watanabe') fioritura prolungata.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Viburnum plicatum$t$) where slug = $t$viburnum-plicatum$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Viburnum plicatum$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Lauro-tino, fusto eretto, 2-4 m, fiorisce novembre-febbraio, foglie persistenti ovali acute verdi-lucenti 3-10 cm, boccioli rosa scuro, fiori rosa-biancastri, bacche blu.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Viburnum tinus$t$) where slug = $t$viburnum-tinus$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Viburnum tinus$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Ramificato, 2,5-3 m, foglie caduche, fiori profumati in cime ombrelliformi (novembre-febbraio); 'Charles Lamont', 'Dawn', 'Deben'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Viburnum x bodnantense$t$) where slug = $t$viburnum-x-bodnantense$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Viburnum x bodnantense$t$ = any(fonti));
update specie set descrizione = descrizione || $t$ Fusto eretto, 1,8-3 m, fiorisce maggio-luglio, ramificazioni ricurvate bruno-giallastre, mazzetti terminali di fiori tubulosi rosa esternamente/bianchi internamente (3 cm); cultivar 'Minuet', 'Nana Variegata', 'Purpurea'; ibridi 'Bristol Ruby', 'Candida', 'Newport Red'.$t$, fonti = array_append(fonti, $t$Il giardino di arbusti (Edicart, 1995) — Weigela florida$t$) where slug = $t$weigela-florida$t$ and not ($t$Il giardino di arbusti (Edicart, 1995) — Weigela florida$t$ = any(fonti));

