insert into specie (nome, nome_scientifico, slug, ciclo_vitale, descrizione, esigenze, fonti, stato_verifica) values ($t$Abelia chinensis$t$, $t$Abelia chinensis$t$, $t$abelia-chinensis$t$, $t$perenne$t$, $t$Abelia di Cina a foglie caduche, soffre il gelo, alta 1,5 m, ramificazioni sottili pubescenti, fiori profumati rosa chiaro, fiorisce luglio-agosto.$t$, $t${"luce": "Pieno sole"}$t$::jsonb, ARRAY[$t$Il giardino di arbusti (Edicart, 1995) — Abelia chinensis$t$]::text[], $t$bozza$t$) on conflict (slug) do nothing;
